, "status": "draft", "id": "5aa0fea8-dcca-56c9-8aa4-f5f6da3e2dad", "subject_id": "1fee289c-4648-5995-8a9d-ba9bbfc960dd", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "霍彦威：天平节度使移平卢、聚兵者。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：公俨不时之官，托云军情所留，帝乃徙天平节度使霍彦威为平卢节度使，聚兵淄州，以图攻取，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "2a14ef6b-a1ab-559d-a924-a4b589bc725d", "subject_id": "b13be5ff-fe0b-5cd5-904e-ebbbb0dfd965", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧明宗纪记霍彦威代符习，聚兵淄州图进取。", "citation": "《旧五代史》卷三十七，段落 jiu-wudaishi-205deb4a7860-p001114；EPUB电子本，纸本及异文待核", "note": "原文：公儼不時赴任，即以霍彥威代符習，聚兵淄州，以圖進取。；核对说明：正文独立补证，不引用夹注通鉴作第二独立来源。", "status": "draft", "id": "28dd69fd-c7ef-54be-bf17-e00896c58049", "subject_id": "c0760434-4b0a-5aa7-9439-fc255a42937b", "source_id": "0e05e690-56d6-5c37-b096-896e9609abd5"}, {"subject_table": "event", "field_path": "description", "claim_text": "王公俨惧霍彦威兵势，开始赴登州任。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：公俨惧，乙未，始之官。；核对说明：始之官为开始赴任，未推乙未已抵登州；恐惧动机为本书叙述。", "status": "draft", "id": "b119f127-b1ad-572b-87d7-9563a49352bc", "subject_id": "5381750e-0081-5e7d-87d7-f25d5190495d", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "926年八月乙未", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：公俨惧，乙未，始之官。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "1b55c9a1-0e38-5ac1-b351-1d2f57b110fd", "subject_id": "5381750e-0081-5e7d-87d7-f25d5190495d", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王公俨：赴登州任者。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：公俨惧，乙未，始之官。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "a4b99206-1e87-5574-92d0-69035fa9b63e", "subject_id": "875bf04b-d17b-5d4f-aacd-a391db61bd94", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧明宗纪记诏使到青州告谕，王公俨即赴所任。", "citation": "《旧五代史》卷三十七，段落 jiu-wudaishi-205deb4a7860-p001114；EPUB电子本，纸本及异文待核", "note": "原文：彥威至淄州，會詔使至青州告諭，公儼即赴所任。；核对说明：旧补告谕环节；不把未名诏使新增人物。", "status": "draft", "id": "d8fd463b-f9cf-50d2-a0ae-431b55f12eaf", "subject_id": "5381750e-0081-5e7d-87d7-f25d5190495d", "source_id": "0e05e690-56d6-5c37-b096-896e9609abd5"}, {"subject_table": "event", "field_path": "description", "claim_text": "霍彦威至青州后追擒王公俨，斩其族党，北海支使韩叔嗣也在其中。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：丁酉，彦威至青州，追擒之，并其族党悉斩之，支使北海韩叔嗣预焉。；核对说明：主族党悉斩范围及人口未具，旧具同谋将校八人不同口径不合死亡总数。预焉依前斩句指韩叔嗣在被斩者之列，不推其具体参与谋乱动作。", "status": "draft", "id": "d7dfc7d0-a9d0-5454-b052-5924a6060730", "subject_id": "89ed8d15-1d8c-528d-a7c2-1b4b21b4fcc1", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "926年八月丁酉据主书；新明宗纪作丁未", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：丁酉，彦威至青州，追擒之，并其族党悉斩之，支使北海韩叔嗣预焉。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "6e351279-b216-508b-9f07-135fda186b23", "subject_id": "89ed8d15-1d8c-528d-a7c2-1b4b21b4fcc1", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "霍彦威：追擒处斩者。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：丁酉，彦威至青州，追擒之，并其族党悉斩之，支使北海韩叔嗣预焉。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "bc3d34cc-cbec-51d3-9972-f0663c4ba7d5", "subject_id": "db62500e-366e-5869-a331-f485cb882661", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王公俨：被捕杀者。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：丁酉，彦威至青州，追擒之，并其族党悉斩之，支使北海韩叔嗣预焉。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "13ad6111-b83f-5fda-a87e-680c1ce6d0df", "subject_id": "f42faf05-8377-5fd1-81db-9425e73b9028", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记韩叔嗣：被杀支使。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：丁酉，彦威至青州，追擒之，并其族党悉斩之，支使北海韩叔嗣预焉。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "f3aab2e8-129d-53d4-bea5-8caefcff0185", "subject_id": "e9ffee66-9e9d-5369-bb60-266b982ff543", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "韩叔嗣：被杀支使。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：丁酉，彦威至青州，追擒之，并其族党悉斩之，支使北海韩叔嗣预焉。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "0aeda489-1548-57ad-903e-0236fd9f701e", "subject_id": "5e0a6c37-818a-5f6c-8739-845571cf9526", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "person", "field_path": "death_year", "claim_text": "王公俨于926年被霍彦威处斩。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：丁酉，彦威至青州，追擒之，并其族党悉斩之，；核对说明：此处追擒并斩主语对象王；死亡记实际行为不以拒命意图推死。", "status": "draft", "id": "affb4b93-9b8c-5db1-ba2c-5dd741f442aa", "subject_id": "74dd140b-b5d5-5fcd-af37-15c675d6c0d5", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "person", "field_path": "death_year", "claim_text": "韩叔嗣于926年王公俨族党被斩时也被杀。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：并其族党悉斩之，支使北海韩叔嗣预焉。；核对说明：预焉承斩事，未具另日。", "status": "draft", "id": "e88d9932-a589-5554-b822-ee85c04f93cc", "subject_id": "e9ffee66-9e9d-5369-bb60-266b982ff543", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧纪记霍彦威奏已斩王公俨及同谋指挥使李谨、王居厚等八人，又记北海县捕获、州东处斩。", "citation": "《旧五代史》卷三十七，段落 jiu-wudaishi-205deb4a7860-p001114；EPUB电子本，纸本及异文待核", "note": "原文：新授青州節度使霍彥威奏，處斬新登州刺史王公儼，及同謀拒命指揮使李謹、王居厚等八人訖。；核对说明：只作奏报补证，八人究竟含王或仅同谋口径不强断；李谨等只在补证名单未另设主线实体。", "status": "draft", "id": "f46ef131-af97-5de3-94fd-4f7a07edbf49", "subject_id": "89ed8d15-1d8c-528d-a7c2-1b4b21b4fcc1", "source_id": "0e05e690-56d6-5c37-b096-896e9609abd5"}, {"subject_table": "event", "field_path": "location_name", "claim_text": "旧明宗纪记公俨被擒于北海县、与同党斩于州东。", "citation": "《旧五代史》卷三十七，段落 jiu-wudaishi-205deb4a7860-p001114；EPUB电子本，纸本及异文待核", "note": "原文：遣人擒公儼於北海縣，與同黨斬於州東。；核对说明：不补现代坐标，旧所述捕杀地点分开。", "status": "draft", "id": "7b96187d-fead-5352-afa6-d7bddd38f330", "subject_id": "89ed8d15-1d8c-528d-a7c2-1b4b21b4fcc1", "source_id": "0e05e690-56d6-5c37-b096-896e9609abd5"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "新明宗纪作丁未霍彦威杀登州刺史王公俨。", "citation": "《新五代史》卷六，段落 xin-wudaishi-b08f244b9241-p000279；EPUB电子本，纸本及异文待核", "note": "原文：丁未，平盧軍節度使霍彥威殺其登州刺史王公儼。；核对说明：与主丁酉不同干支，保留电子本异文待纸本核，不自行选择一个真日。", "status": "draft", "id": "d34f301e-5e29-55f3-b580-52f1c02591ed", "subject_id": "89ed8d15-1d8c-528d-a7c2-1b4b21b4fcc1", "source_id": "0f1ef6e8-6f65-5ba0-9ca2-70cce6aac061"}, {"subject_table": "event", "field_path": "description", "claim_text": "新符习传称房知温擒杀王公俨。", "citation": "《新五代史》卷二十六，段落 xin-wudaishi-b08f244b9241-p000921；EPUB电子本，纸本及异文待核", "note": "原文：公儼不時承命，知溫擒而殺之。；核对说明：传中知温与两书帝纪及主霍彦威矛盾，作为书证异说，不新建另一次杀公俨。", "status": "draft", "id": "46c35362-738d-5ff9-904f-c0fbf4b34430", "subject_id": "89ed8d15-1d8c-528d-a7c2-1b4b21b4fcc1", "source_id": "23c0baa3-5d28-57cb-bc16-bca5a5d4daf9"}, {"subject_table": "event", "field_path": "description", "claim_text": "韩熙载将奔吴，密告李谷；李谷送至正阳，与他痛饮告别。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p050·原文件第55行", "note": "原文：其子熙载将奔吴，密告其友汝阴进士李谷，谷送至正阳，痛饮而别。；核对说明：将奔是准备，送至正阳不等已抵吴都或已被任官；吴指当时吴政权，不提前叫南唐。", "status": "draft", "id": "0f663972-dd32-56b1-80a4-a33cebfc3d37", "subject_id": "8522736f-a350-5106-8450-c9336b7047d8", "source_id": "995fcf12-91a1-5019-a7dc-6b9a3152985c"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "926年八月韩叔嗣被杀条之后，具体日未载", "citation": "卷275·同光四年（926）·zztj-v2